    "easy",
    "\u56de\u6eaf/\u4f4d\u8fd0\u7b97",
    "\u4e00\u6b21 \u4f4d\u7ffb\u8f6c\u00a0\u5b9a\u4e49\u4e3a\u5c06\u6570\u5b57\u00a0x\u00a0\u4e8c\u8fdb\u5236\u4e2d\u7684\u4e00\u4e2a\u4f4d\u8fdb\u884c \u7ffb\u8f6c\u00a0\u64cd\u4f5c\uff0c\u5373\u5c06\u00a00\u00a0\u53d8\u6210\u00a01\u00a0\uff0c\u6216\u8005\u5c06\u00a01\u00a0\u53d8\u6210\u00a00\u00a0\u3002\n\n\t\u6bd4\u65b9\u8bf4\uff0cx = 7\u00a0\uff0c\u4e8c\u8fdb\u5236\u8868\u793a\u4e3a\u00a0111\u00a0\uff0c\u6211\u4eec\u53ef\u4ee5\u9009\u62e9\u4efb\u610f\u4e00\u4e2a\u4f4d\uff08\u5305\u542b\u6ca1\u6709\u663e\u793a\u7684\u524d\u5bfc 0 \uff09\u5e76\u8fdb\u884c\u7ffb\u8f6c\u3002\u6bd4\u65b9\u8bf4\u6211\u4eec\u53ef\u4ee5\u7ffb\u8f6c\u6700\u53f3\u8fb9\u4e00\u4f4d\u5f97\u5230\u00a0110\u00a0\uff0c\u6216\u8005\u7ffb\u8f6c\u53f3\u8fb9\u8d77\u7b2c\u4e8c\u4f4d\u5f97\u5230\u00a0101\u00a0\uff0c\u6216\u8005\u7ffb\u8f6c\u53f3\u8fb9\u8d77\u7b2c\u4e94\u4f4d\uff08\u8fd9\u4e00\u4f4d\u662f\u524d\u5bfc 0 \uff09\u5f97\u5230\u00a010111\u00a0\u7b49\u7b49\u3002\n\n\u7ed9\u4f60\u4e24\u4e2a\u6574\u6570\u00a0start \u548c\u00a0goal\u00a0\uff0c\u8bf7\u4f60\u8fd4\u56de\u5c06\u00a0start\u00a0\u8f6c\u53d8\u6210\u00a0goal\u00a0\u7684\u00a0\u6700\u5c11\u4f4d\u7ffb\u8f6c\u00a0\u6b21\u6570\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1astart = 10, goal = 7\n\u8f93\u51fa\uff1a3\n\u89e3\u91ca\uff1a10 \u548c 7 \u7684\u4e8c\u8fdb\u5236\u8868\u793a\u5206\u522b\u4e3a 1010 \u548c 0111 \u3002\u6211\u4eec\u53ef\u4ee5\u901a\u8fc7 3 \u6b65\u5c06 10 \u8f6c\u53d8\u6210 7 \uff1a\n- \u7ffb\u8f6c\u53f3\u8fb9\u8d77\u7b2c\u4e00\u4f4d\u5f97\u5230\uff1a1010 -> 1011 \u3002\n- \u7ffb\u8f6c\u53f3\u8fb9\u8d77\u7b2c\u4e09\u4f4d\uff1a1011 -> 1111 \u3002\n- \u7ffb\u8f6c\u53f3\u8fb9\u8d77\u7b2c\u56db\u4f4d\uff1a1111 -> 0111 \u3002\n\u6211\u4eec\u65e0\u6cd5\u5728 3 \u6b65\u5185\u5c06 10 \u8f6c\u53d8\u6210 7 \u3002\u6240\u4ee5\u6211\u4eec\u8fd4\u56de 3 \u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1astart = 3, goal = 4\n\u8f93\u51fa\uff1a3\n\u89e3\u91ca\uff1a3 \u548c 4 \u7684\u4e8c\u8fdb\u5236\u8868\u793a\u5206\u522b\u4e3a 011 \u548c 100 \u3002\u6211\u4eec\u53ef\u4ee5\u901a\u8fc7 3 \u6b65\u5c06 3 \u8f6c\u53d8\u6210 4 \uff1a\n- \u7ffb\u8f6c\u53f3\u8fb9\u8d77\u7b2c\u4e00\u4f4d\uff1a011 -> 010 \u3002\n- \u7ffb\u8f6c\u53f3\u8fb9\u8d77\u7b2c\u4e8c\u4f4d\uff1a010 -> 000 \u3002\n- \u7ffb\u8f6c\u53f3\u8fb9\u8d77\u7b2c\u4e09\u4f4d\uff1a000 -> 100 \u3002\n\u6211\u4eec\u65e0\u6cd5\u5728 3 \u6b65\u5185\u5c06 3 \u53d8\u6210 4 \u3002\u6240\u4ee5\u6211\u4eec\u8fd4\u56de 3 \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t0 <= start, goal <= 109\n\n\u00a0\n\n\u6ce8\u610f\uff1a\u672c\u9898\u4e0e\u00a0461. \u6c49\u660e\u8ddd\u79bb\u00a0\u76f8\u540c\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1astart\u3001goal\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def minBitFlips(self, start: int, goal: int) -> int:\n        res = 0\n        tmp = start ^ goal\n        while tmp:\n            res += tmp & 1\n            tmp >>= 1\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minBitFlips(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
